  if(/drive\.google\.com\/drive\/(u\/\d+\/)?folders/.test(u))return ['📁','Pasta do Drive'];if(/\.pdf(\?|$)/.test(u))return ['📕','PDF'];
  if(/canva\.(com|link)/.test(u))return ['🎨','Canva'];if(/youtu\.?be/.test(u))return ['▶️','Vídeo'];if(/drive\.google\.com/.test(u))return ['🗂️','Arquivo no Drive'];
